/* State oracle for src/tu/grtclink.rs (generated by gen_target_stage.py): the game TU #included verbatim
 * (shipping contraction via run.py), every callee outside it a tracing stub, cases on a synthetic
 * state from the shared seeded stream. tests/tu_grtclink.rs replays them. */
#include "melee/gr/grtclink.c"
#include "oracle.h"
#include "tu_gr_common.h"
#include "tu_grtclink_stubs.inc"

static void state(void)
{
    printf("rs %u\n", ORS);
    printf("si %d %d\n", (int) stage_info.unk8C.b4, (int) stage_info.unk8C.b5);
    DUMPARENA();
    state_end();
}

#define FN(x) fnreg(#x, (void*) x)
int main(void)
{
    int c;
    arena_init();
    SIZE(Ground);
    SIZE(HSD_GObj);
    SIZE(HSD_JObj);
    SIZE(StageCallbacks);
    SIZE(StageData);
    reg("cb", grTCLink_StageCallbacks, sizeof(grTCLink_StageCallbacks));
    reg("sd", &grTCLink_StageData, sizeof(grTCLink_StageData));
    reg("dat", grTCLink_StageData.data1, 16);
    FN(grTCLink_8021FF44);
    FN(grTCLink_OnInit);
    FN(grTclink_UnkStage0_OnLoad);
    FN(grTclink_UnkStage0_OnStart);
    FN(grTCLink_8021FFE0);
    FN(grTCLink_8021FFE8);
    FN(grTCLink_80220218);
    FN(grTCLink_80220220);
    FN(grTCLink_802200D0);
    FN(grTCLink_802200FC);
    FN(grTCLink_80220104);
    FN(grTCLink_80220108);
    FN(stageGObj1_OnInit);
    FN(grTCLink_802201EC);
    FN(stageGObj1_GObjProc);
    FN(grTCLink_80220214);
    FN(stageGObj2_OnInit);
    FN(grTCLink_8022015C);
    FN(stageGObj2_GObjProc);
    FN(grTCLink_80220198);
    fnreg("grDisplay_801C5DB0", (void*) grDisplay_801C5DB0);
    DUMP("cb", grTCLink_StageCallbacks);
    DUMP("sd", grTCLink_StageData);
    state_end();

    for (c = 0; c < 60; c++) { /* grTCLink_8021FFE8 and the callbacks it installs */
        CASE(c);
        rseed(100 + c);
        gr_reset();
        stage_info.unk8C.b4 = rnd() & 1;
        stage_info.unk8C.b5 = rnd() & 1;
        printf("r"); TRP(grTCLink_8021FFE8(c % 3)); printf("\n");
        state();
    }
    for (c = 0; c < 20; c++) { /* OnInit / OnStart / OnLoad / OnDemoInit */
        CASE(1000 + c);
        rseed(2000 + c);
        gr_reset();
        grTCLink_OnInit();
        state();
        grTclink_UnkStage0_OnStart();
        grTclink_UnkStage0_OnLoad();
        grTCLink_8021FF44((int) rnd());
        state();
    }
    for (c = 0; c < 12; c++) { /* every stage callback of the three gobjs */
        HSD_GObj* g;
        CASE(2000 + c);
        rseed(3000 + c);
        gr_reset();
        g = mkgobj();
        grTCLink_802200D0(g); state();
        printf("r %d\n", (int) grTCLink_802200FC(g));
        grTCLink_80220104(g); grTCLink_80220108(g); state();
        stageGObj1_OnInit(g); state();
        printf("r %d\n", (int) grTCLink_802201EC(g));
        stageGObj1_GObjProc(g); grTCLink_80220214(g); state();
        stageGObj2_OnInit(g); state();
        printf("r %d\n", (int) grTCLink_8022015C(g));
        stageGObj2_GObjProc(g); grTCLink_80220198(g); state();
        printf("r %d\n", (int) grTCLink_8021FFE0());
        printf("r"); TRP(grTCLink_80220218((int) rnd())); printf("\n");
        {
            Vec3 v;
            int a1;
            HSD_JObj* j;
            v.x = rf(); v.y = rf(); v.z = rf();
            a1 = (int) rnd();
            j = mkjobj();
            printf("r %d\n", (int) grTCLink_80220220(&v, a1, j));
        }
        state();
    }
    return 0;
}
